import{_ as t,o as s,c as n,ae as e}from"./chunks/framework.CkRokae0.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/04-adr/why-adr.md","filePath":"sessions/04-adr/why-adr.md"}'),r={name:"sessions/04-adr/why-adr.md"};function d(o,a,i,l,h,p){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h2 id="要約" tabindex="-1">要約 <a class="header-anchor" href="#要約" aria-label="Permalink to &quot;要約&quot;">​</a></h2><p>判断の理由が記録されていないと、組織内で知識が散失し、同じ議論の繰り返しやリスク判断の見落としが起こります。ADR はそれを防ぎます。</p><h2 id="よくある問題シナリオ" tabindex="-1">よくある問題シナリオ <a class="header-anchor" href="#よくある問題シナリオ" aria-label="Permalink to &quot;よくある問題シナリオ&quot;">​</a></h2><h3 id="シナリオ1-「なぜ」が消える" tabindex="-1">シナリオ1：「なぜ」が消える <a class="header-anchor" href="#シナリオ1-「なぜ」が消える" aria-label="Permalink to &quot;シナリオ1：「なぜ」が消える&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当時の判断者：「複雑な計算が必要だから非同期処理にした」</span></span>
<span class="line"><span>6ヶ月後のメンバー：「なんでこんなに複雑な非同期？同期にして簡潔にしよう」</span></span>
<span class="line"><span>  → コード改変 → 本番でタイムアウトエラー多発</span></span></code></pre></div><h3 id="シナリオ2-誤った設計判断" tabindex="-1">シナリオ2：誤った設計判断 <a class="header-anchor" href="#シナリオ2-誤った設計判断" aria-label="Permalink to &quot;シナリオ2：誤った設計判断&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当初決定：「小規模チームだからモノリシック」</span></span>
<span class="line"><span>プロジェクト成長後：「マイクロサービス化すべきでは」</span></span>
<span class="line"><span>  → しかし当初の理由を知らないため、無駄な検討と時間浪費</span></span></code></pre></div><h3 id="シナリオ3-オンボーディング時間の浪費" tabindex="-1">シナリオ3：オンボーディング時間の浪費 <a class="header-anchor" href="#シナリオ3-オンボーディング時間の浪費" aria-label="Permalink to &quot;シナリオ3：オンボーディング時間の浪費&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ADRなし：</span></span>
<span class="line"><span>  新メンバー「なぜ NoSQL？」</span></span>
<span class="line"><span>  → 詳しい人に質問 → 「昔の決定」→ もう一度議論 → 同じ結論</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ADRあり：</span></span>
<span class="line"><span>  新メンバー「なぜ NoSQL？」→ ADR 参照 → 即理解</span></span></code></pre></div><h2 id="adr-で改善されること-5つのメリット" tabindex="-1">ADR で改善されること（5つのメリット） <a class="header-anchor" href="#adr-で改善されること-5つのメリット" aria-label="Permalink to &quot;ADR で改善されること（5つのメリット）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>メリット</th><th>効果</th></tr></thead><tbody><tr><td><strong>1. 知識の保持</strong></td><td>判断した時点での背景や制約が記録されるため、担当者が変わっても判断の意図が失われません。</td></tr><tr><td><strong>2. 判断の検証</strong></td><td>当時の前提が変わったのかを確認できます。例：「当時は A チームが小さかったから簡潔設計にした。今は 10 倍に成長した。再評価の価値あり」。</td></tr><tr><td><strong>3. 誤った変更の防止</strong></td><td>背景を知らずに「古い設計だから」と改変することを防ぎます。理由を知ると「その判断は今も有効」と気づきやすくなります。</td></tr><tr><td><strong>4. オンボーディングの高速化</strong></td><td>新メンバーが設計背景を短時間で理解できるため、同じ質問・議論の繰り返しがなくなります。</td></tr><tr><td><strong>5. 意思決定のトレーサビリティ</strong></td><td>「いつ誰がどんな理由で判断したか」が記録されるため、アカウンタビリティ（説明責任）が明確になります。</td></tr></tbody></table><h2 id="よくある失敗パターンと対策" tabindex="-1">よくある失敗パターンと対策 <a class="header-anchor" href="#よくある失敗パターンと対策" aria-label="Permalink to &quot;よくある失敗パターンと対策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>失敗パターン</th><th>原因</th><th>対策</th></tr></thead><tbody><tr><td><strong>❌ 失敗1：書かない</strong></td><td>運用の習慣がない、完璧を目指す</td><td>完璧を目指さない。迷ったときだけ、短く書く。始めは1ヶ月に1～2件程度でOK。</td></tr><tr><td><strong>❌ 失敗2：過度に詳細</strong></td><td>設計書と混同している、背景の全て書こうとする</td><td>背景は「必要十分」に限定。詳細は別紙設計書にリンク。5～10分で読めるレベル。</td></tr><tr><td><strong>❌ 失敗3：強制的・ルール化しすぎ</strong></td><td>全判断に ADR を強制、承認フロー化</td><td>「重要度が高い判断だけ」と明示。運用負荷が小さい範囲で。</td></tr><tr><td><strong>❌ 失敗4：古いまま放置</strong></td><td>一度書いたら更新しない</td><td>定期的（年1～2回）に「この前提は今も有効か」を確認。無効なら Update。</td></tr><tr><td><strong>❌ 失敗5：過剰ドキュメント化</strong></td><td>細かい実装判断まで ADR 化</td><td>長期影響がない判断は ADR にしない。ドキュメント負荷を優先順位で判断。</td></tr></tbody></table><h2 id="adr-が効かない-不要なケース" tabindex="-1">ADR が効かない／不要なケース <a class="header-anchor" href="#adr-が効かない-不要なケース" aria-label="Permalink to &quot;ADR が効かない／不要なケース&quot;">​</a></h2><ul><li><strong>細かい実装判断</strong>（変数名、関数分割、フォーマット）</li><li><strong>毎日のように変わる設定</strong>（ログレベル、タイムアウト値など一時的調整）</li><li><strong>仕様が明確で自明な判断</strong>（「SQLインジェクション対策をする」など）</li><li><strong>可逆的な決定</strong>（簡単に戻せて、コスト・影響が小さい）</li></ul><p>これらに ADR を作るとドキュメント負荷が増えるだけです。</p><hr><h2 id="ナビゲーション" tabindex="-1">ナビゲーション <a class="header-anchor" href="#ナビゲーション" aria-label="Permalink to &quot;ナビゲーション&quot;">​</a></h2><p><a href="./what-is-adr.html">← 前へ: ADRとは</a> · <a href="./how-to-use.html">次へ: 使い方 →</a> · <a href="./">ADRトップへ</a></p>`,19)])])}const b=t(r,[["render",d]]);export{g as __pageData,b as default};
